Let $d \geq 5$ and $n \geq 4$, and let $V \in \mathrm{Conf}_{d,n}$. There exists $b = b(d,n) > 0$ such that, for any $\delta \in (0,\frac12)$, there exist $a = a(d,n,\delta) > 0$ and a $\mathbf{P}_V$-a.s.\@ finite random time $\theta = \theta (d,n,\delta) \in \mathbb{N}$
 at which there is a clustering $\mathcal{W} \in \mathrm{Clust}_{a,b}^\bullet (U_\theta)$ such that the natural partitioning $(\mathcal{U}_t)_{t \geq \theta}$ of $(U_t)_{t \geq \theta}$ with $\mathcal{W}$ satisfies 
\begin{equation}
\mathcal{U}_t \in \mathrm{Clust}_{g(t-\theta),b}^\bullet (U_t), \quad t > \theta,
\end{equation}
where $g(s) = s^{\frac12 - \delta}$ for $s \geq 0$.

Fix $d \geq 5$ and $n \geq 4$. For every $a > 0$, there exist $N = N (a,d,n) \in \mathbb{N}$ and $p = p(a,d,n) \in (0,1]$ such that, for any $V \in \mathrm{Conf}_{d,n}$,
\begin{equation}
\mathbf{P}_{V} \left( \mathrm{Clust}_{a,1}^\bullet (U_N) \cap \mathrm{Ref}^\times \neq \emptyset \right) \geq p.
\end{equation}

There exists $b = b(d,n) > 0$ such that, for any $\delta \in (0,\frac12)$, there exists $\alpha = \alpha (b,d,n,\delta)$, such that, if $a \geq \alpha$ then, 
\begin{equation}
\mathsf{G} \cap \{\mathcal{V}_0 \in \mathrm{Ref}^\times\} \subseteq \left\{ (\mathcal{V}_t)_{t \geq 0} \in \mathrm{Grow}_{\tilde a,b,\delta} \right\},
\end{equation}
where $\tilde a = a^{0.99}$.

If $U \in \mathrm{Conf}_{d,n}$ and $a \in \mathbb{Z}_{\geq 1}$, then $\mathcal{A}_{alg1} (U,a)$ can be lined-up with separation $dn^2a$.

There exists $\alpha_3 = \alpha_3 (d,n) \in \mathbb{Z}_{\geq 1}$ such that, if $a \in \mathbb{Z}_{\geq \alpha_3}$, then there are $N_3 = N_3 (a,d,n) \in \mathbb{N}$ and $p_3 = p_3 (a,d,n) \in (0,1]$ such that, if $\mathcal{C} \in \mathrm{Conf}_{d,n}^\times$ can be lined-up with separation $n^2 a$, then 
\begin{equation}
\mathbf{P}_{U} \Big( U_{N_3} = \pi \big( \mathcal{A}_{alg3} (\mathcal{L}(\mathcal{C}),a) \big) \Big) \geq p_3.
\end{equation}

Fix $d \geq 5$ and $n \geq 4$, and let $a,b > 0$. There are constants $\alpha_0 = \alpha_0 (b,d,n)$ and $c = c(b,d,n)$ such that, if $a \geq \alpha_0$, then, for every $\mathcal{C}_0, \mathcal{C}_1 \in \mathrm{Clust}_{a,b}^\bullet$,
\begin{equation}
\mathbf{P}_{\mathcal{C}_0} (\mathcal{U}_1 = \mathcal{C}_1) \geq \left( 1 - c \left(a^{-1} \log a\right)^{d-2} \right) \mathbf{Q}_{\mathcal{C}_0} (\mathcal{V}_1 = \mathcal{C}_1).
\end{equation}

There exists $\alpha = \alpha (d,n) > 0$ such that, if $\mathcal{C}_0 \in \mathrm{Ref}^\times$ satisfies $\mathrm{sep} (\mathcal{C}_0) \geq \alpha$, then
\begin{equation}
\mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{G} (\ell)^{\mathsf{c}} \mid \mathscr{F}_{\eta_{\ell-1}} \right) \mathbf{1}_{\mathsf{G}(\ell-1)} \leq 8 \ell^{-2}, \quad \ell \geq 1,
\end{equation}
where $\eta_{\ell-1}$ denotes $\xi_{N(t_{\ell-1})+1}$.

For each $\ell \geq 1$, $\mathsf{F} (\ell) \subseteq \mathsf{G} (\ell)$.

There exists $\alpha = \alpha (d,n)$ such that, if $\mathcal{C}_0 \in \mathrm{Ref}^\times$ satisfies $\mathrm{sep} (\mathcal{C}_0) \geq \alpha$, then
\begin{equation*}
\mathbf{Q}_{\mathcal{C}_0} \big( \mathsf{F}_1^{i,j} (\ell) \cap \mathsf{F}_3^{i,j} (\ell)^{\mathsf{c}} \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \big) \leq (8n\ell)^{-2}.
\end{equation*}

Fix $d \geq 5$ and $n \geq 4$. Let $a,b > 0$, let $\mathcal{C}_0, \mathcal{C}_1 \in \mathrm{Clust}_{a,b}^\bullet$, and denote $U_0 = \cup_j \mathcal{C}_0^j$. If $a$ is at least $\max\{e^{2b},8\sqrt{d}\}$,  
then, for any $x \in U_0$ and $y \in \mathbb{Z}^d$ such that 
\begin{equation}
\mathcal{C}_1 = (\mathcal{C}_0 \setminus^{\hspace{-0.2em} [x]_{\mathcal{C}_0}} \{x\}) \cup^{[x]_{\mathcal{C}_0}} \{y\},
\end{equation}
the following equivalence holds
\begin{equation}
p_{U_0} (x,y) > 0 \iff q_{\mathcal{C}_0} ([x]_{\mathcal{C}_0},x,y) > 0.
\end{equation}

Let $d \geq 4$. There is a constant $c = c (d)$ such that, if $U \in \mathrm{Conf}_d$ can be partitioned into $\mathcal{P} = (\mathcal{P}^i)_{i=1}^k$ such that $|\mathcal{P}^i| \leq 3$ for every $1 \leq i \leq k$ and $\mathrm{sep} (\mathcal{P}) \geq \kappa$, then 
\begin{equation}
\mathbb{H}_U (x) \geq \big(1 - c |U| \mathrm{sep}(\mathcal{P}) ^{2-d} \big) \mathbb{H}_{\mathcal{P}} ([x]_{\mathcal{P}},x), \quad x \in U.
\end{equation}

Let $a \geq \kappa$, $b > 0$, and $d \geq 4$. There is a constant $c = c(b,d)$ such that, if $U \in \mathrm{Conf}_d$ has an $(a,b)$ DOT clustering $\mathcal{P}$, 
then, for every $x \in U$ and every $y$ in the exterior boundary of $A = \mathcal{P}^{[x]_{\mathcal{P}}} {\setminus} \{x\}$, 
\begin{equation*}
\mathbb{P}_x (S_{\tau_{U {\setminus} \{x\}}-1} = y \,\vert\, \tau_{U {\setminus} \{x\}} < \infty) \geq \left(1 - c |U| \left( \frac{\log \mathrm{sep} (\mathcal{P})}{\mathrm{sep} (\mathcal{P})} \right)^{d-2} \right) \mathbb{P}_x (S_{\tau_A-1} = y \,\vert\, \tau_A < \infty).
\end{equation*}
